@Controller('api/operations/staff-actors')
export class StaffActorController {
  private readonly defaultLimit = 50;
  private readonly maxLimit = 100;

  constructor(
    private readonly staffActors: StaffActorService,
  ) {}

  private async authorizeSupervisor(
    actorId?: string,
    actorRole?: string,
  ): Promise<void> {
    if (!actorId || !actorRole) {
      throw new UnauthorizedException(
        'Actor context is required',
      );
    }

    if (actorRole !== 'SUPERVISOR') {
      throw new ForbiddenException(
        'Supervisor authority is required',
      );
    }

    const actor =
      await this.staffActors.resolveActiveActorWithRole(
        actorId,
        'SUPERVISOR',
      );

    if (!actor) {
      throw new ForbiddenException(
        'Canonical active Supervisor is required',
      );
    }
  }

  private parseLimit(
    raw?: string,
  ): number {
    if (
      raw === undefined ||
      raw.trim() === ''
    ) {
      return this.defaultLimit;
    }

    if (!/^\d+$/.test(raw)) {
      throw new BadRequestException(
        'limit must be an integer',
      );
    }

    const limit = Number(raw);

    if (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > this.maxLimit
    ) {
      throw new BadRequestException(
        `limit must be between 1 and ${this.maxLimit}`,
      );
    }

    return limit;
  }

  private parseRole(
    raw?: string,
  ): StaffRole | undefined {
    if (
      raw === undefined ||
      raw === '' ||
      raw === 'ALL'
    ) {
      return undefined;
    }

    const allowed: StaffRole[] = [
      'CAREGIVER',
      'NURSE',
      'SUPERVISOR',
      'CARE_MANAGER',
    ];

    if (
      !allowed.includes(
        raw as StaffRole,
      )
    ) {
      throw new BadRequestException(
        'Invalid role',
      );
    }

    return raw as StaffRole;
  }

  private parseStatus(
    raw?: string,
  ): StaffStatus | undefined {
    if (
      raw === undefined ||
      raw === '' ||
      raw === 'ALL'
    ) {
      return undefined;
    }

    const allowed: StaffStatus[] = [
      'ACTIVE',
      'INACTIVE',
      'SUSPENDED',
      'ARCHIVED',
    ];

    if (
      !allowed.includes(
        raw as StaffStatus,
      )
    ) {
      throw new BadRequestException(
        'Invalid status',
      );
    }

    return raw as StaffStatus;
  }

